const times=['07:00','08:30','10:00','11:30','13:00','14:30'];
const subjects=['Mathematics','English','General Science','Filipino','Social Studies','Computer Studies','Biology','Physical Education'];
const teachers=['Ms. Santos','Mr. Cruz','Ms. Reyes','Mr. Dela Cruz','Ms. Garcia','Mr. Mendoza'];
const sections=['Grade 10 · Einstein','Grade 10 · Newton','Grade 9 · Rizal','Grade 8 · Mabini','Grade 7 · Bonifacio'];
const storedRooms=JSON.parse(localStorage.getItem('cdm-rooms')||'null');if(storedRooms)Object.keys(rows).forEach(k=>{if(Array.isArray(storedRooms[k]))rows[k]=storedRooms[k]});
const allRooms=Object.values(rows).flat();
const makeSchedule=()=>{let out=[];const teaching=allRooms.filter(r=>['Classroom','Laboratory','Computer lab'].includes(r.type));teaching.forEach((r,i)=>{for(let d=0;d<5;d++){if((i+d)%4===0)continue;let n=(i*3+d)%times.length;out.push({id:`demo-${r.id}-${d}`,roomId:r.id,day:d,time:times[n],end:times[n].slice(0,3)+String((Number(times[n].slice(3))+30)%60).padStart(2,'0'),subject:subjects[(i+d*2)%subjects.length],teacher:teachers[(i+d)%teachers.length],section:sections[(i+d)%sections.length],demo:true});}});return out};
let schedule=JSON.parse(localStorage.getItem('cdm-schedule')||'null')||makeSchedule();
let state={floor:1,selected:null,search:'',query:'',day:new Date().getDay()>=1&&new Date().getDay()<=5?new Date().getDay()-1:0,mode:'List View',tab:'home',zoom:1,admin:false,adminOpen:false,adminSection:'rooms',editScheduleId:null};
const save=()=>{localStorage.setItem('cdm-rooms',JSON.stringify(rows));localStorage.setItem('cdm-schedule',JSON.stringify(schedule));};
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const floorName=n=>['','First','Second','Third','Fourth'][n];
function status(r){let now=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Manila'})),d=now.getDay()-1,m=now.getHours()*60+now.getMinutes(),entries=schedule.filter(s=>s.roomId===r.id&&s.day===d).sort((a,b)=>a.time.localeCompare(b.time));let active=entries.find(s=>{let [h,x]=s.time.split(':').map(Number),[eh,ex]=s.end.split(':').map(Number);return m>=h*60+x&&m<eh*60+ex});let next=entries.find(s=>{let [h,x]=s.time.split(':').map(Number);return h*60+x>m});return active?{key:'occupied',label:'In class',entry:active}:next?{key:'upcoming',label:'Upcoming',entry:next}:entries.length?{key:'available',label:'Available'}:{key:'none',label:'No schedule'}}
const mapResults=()=>allRooms.filter(r=>!state.search||r.name.toLowerCase().includes(state.search.toLowerCase()));
function render(){const avail=allRooms.map(status).filter(s=>s.key==='available').length, occupied=allRooms.map(status).filter(s=>s.key==='occupied').length;$('#app').innerHTML=`<header class="nav"><a class="brand" href="#" data-tab="home"><img src="/school-seal.jpg"><span>COLEGIO DE MONTALBAN<small>RODRIGUEZ, RIZAL</small></span></a><nav><button data-tab="home" class="${state.tab==='home'?'active':''}">Home</button><button data-tab="map" class="${state.tab==='map'?'active':''}">Campus map</button><button data-tab="finder" class="${state.tab==='finder'?'active':''}">Find my classes</button></nav><button class="admin-btn" id="adminBtn">${state.admin?'Admin dashboard':'Admin login'} <span>↗</span></button></header>
${state.tab==='home'?home(avail,occupied):state.tab==='finder'?finder():mapPage()}
<footer><div class="footbrand"><img src="/school-seal.jpg"><b>Colegio de Montalban</b></div><span>Campus information · Demonstration schedule data</span><span>All times shown in Asia/Manila</span></footer>${state.adminOpen?adminPanel():''}`;bind();}
function home(avail,occupied){return `<main><section class="hero"><div class="hero-copy"><div class="eyebrow"><i></i> YOUR CAMPUS, AT A GLANCE</div><h1>Find your class.<br><em>Know your campus.</em></h1><p>Explore Colegio de Montalban, discover your classroom, and plan your week with confidence.</p><div class="hero-actions"><button class="primary" data-tab="map">Explore campus map <b>↗</b></button><button class="secondary" data-tab="finder">Find my classes <b>→</b></button></div><div class="hero-meta"><span><b>04</b> floors</span><span><b>${allRooms.length}</b> mapped places</span><span><b>LIVE</b> room status</span></div></div><div class="hero-visual"><div class="photo-frame"><img src="/floor-plans/floor-1.png" alt="First floor plan"><div class="photo-shade"></div><div class="photo-label"><small>EXPLORE YOUR CAMPUS</small><b>Every room.<br>One easy map.</b></div><div class="map-pin">⌖</div></div><div class="floating-stat"><span class="pulse"></span><div><b>${avail} rooms available</b><small>Updated from today's schedule</small></div><div class="stat-number">${occupied}<small>IN CLASS</small></div></div><div class="floor-chip">↗ &nbsp; 4 FLOOR PLANS</div></div></section><section class="feature-strip"><div class="section-label">MADE FOR YOUR SCHOOL DAY</div><h2>Your day, made easier.</h2><div class="features"><button class="feature" data-tab="map"><i class="icon">⌖</i><span><b>Explore the campus</b><small>Find every room across four floors.</small></span><span class="arrow">↗</span></button><button class="feature" data-tab="finder"><i class="icon sun">▤</i><span><b>Find your classes</b><small>Search your weekly schedule.</small></span><span class="arrow">↗</span></button><button class="feature" data-next><i class="icon amber">◷</i><span><b>Find your next class</b><small>Jump to your next classroom.</small></span><span class="arrow">↗</span></button><button class="feature" data-tab="map"><i class="icon green">◉</i><span><b>Room availability</b><small>${avail} rooms free right now.</small></span><span class="arrow">↗</span></button></div></section></main>`}
function mapPage(){let floorRooms=rows[state.floor]||[];let s=allRooms.find(r=>r.id===state.selected);return `<main class="workspace"><div class="page-heading"><div><div class="eyebrow">CAMPUS DIRECTORY</div><h1>Explore the campus</h1><p>Choose a floor or room to see where your day takes you.</p></div><label class="searchbox">⌕ <input id="mapSearch" placeholder="Search a room or facility" value="${esc(state.search)}"><kbd>⌘ K</kbd></label></div><div class="map-layout"><section class="map-card"><div class="map-toolbar"><div class="floor-tabs">${[1,2,3,4].map(n=>`<button data-floor="${n}" class="${state.floor===n?'chosen':''}">${n}<sup>${['','ST','ND','RD','TH'][n]}</sup></button>`).join('')}</div><div class="zoom-tools"><button id="zoomOut" aria-label="Zoom out">−</button><button id="zoomIn" aria-label="Zoom in">+</button><button id="resetZoom" aria-label="Reset view">↺</button></div></div><div class="map-canvas" id="canvas"><div class="plan" style="transform:scale(${state.zoom})"><img src="/floor-plans/floor-${state.floor}.png" alt="${floorName(state.floor)} floor plan"><svg viewBox="0 0 1920 1080" role="group" aria-label="Interactive room map">${floorRooms.map(r=>{let st=status(r);return `<g class="room-hit ${st.key} ${state.selected===r.id?'selected':''} ${state.search&&!r.name.toLowerCase().includes(state.search.toLowerCase())?'dimmed':''}" data-room="${r.id}" tabindex="0" role="button" aria-label="${esc(r.name)}, ${st.label}"><rect x="${r.x}" y="${r.y}" width="${r.w}" height="${r.h}" rx="4"/><title>${esc(r.name)} — ${st.label}</title></g>`}).join('')}</svg></div><div class="map-watermark">CDM&nbsp; · &nbsp;${floorName(state.floor).toUpperCase()} FLOOR</div></div><div class="map-legend"><span><i class="available"></i>Available</span><span><i class="occupied"></i>In class</span><span><i class="upcoming"></i>Upcoming</span><span><i class="none"></i>No schedule</span><small>Demo schedules · Philippine time</small></div></section><aside class="details">${s?details(s):`<div class="empty-details"><div class="empty-icon">⌖</div><h3>Pick a place on the map</h3><p>Select any room to view its floor, availability, and schedule.</p><div class="quick-title">QUICK SEARCH</div>${floorRooms.filter(r=>r.type==='Classroom').slice(0,5).map(r=>`<button class="quick-room" data-select="${r.id}">${r.name}<span>→</span></button>`).join('')}</div>`}</aside></div></main>`}
function details(r){let st=status(r),list=schedule.filter(s=>s.roomId===r.id&&s.day===state.day).sort((a,b)=>a.time.localeCompare(b.time));return `<div class="detail-top"><span class="type-chip">${esc(r.type)}</span><button class="close" id="clearSelection">×</button></div><h2>${esc(r.name)}</h2><p class="muted">${floorName(r.floor)} floor · Colegio de Montalban</p><div class="statusline"><i class="${st.key}"></i><b>${st.label}</b>${st.entry?`<span>${st.entry.time} · ${st.entry.subject}</span>`:''}</div><p class="description">${esc(r.description)}</p><div class="schedule-head"><b>Weekly timetable</b><span>DEMO DATA</span></div><div class="day-pills">${['M','T','W','T','F'].map((v,i)=>`<button data-day="${i}" class="${state.day===i?'on':''}">${v}</button>`).join('')}</div>${list.length?list.map(s=>`<div class="class-row"><span class="time">${s.time}</span><span class="class-info"><b>${esc(s.subject)}</b><small>${esc(s.teacher)} · ${esc(s.section)}</small></span><button class="tiny-map" data-class="${s.id}" title="Show class on map">↗</button></div>`).join(''):`<div class="no-classes">No scheduled classes on ${['Monday','Tuesday','Wednesday','Thursday','Friday'][state.day]}.</div>`}<button class="outline full" data-tab="finder">Find a class here <span>→</span></button>`}
function finder(){let q=state.query.toLowerCase(),matches=schedule.filter(s=>{let r=allRooms.find(x=>x.id===s.roomId);return [s.subject,s.teacher,s.section,r?.name,...['Monday','Tuesday','Wednesday','Thursday','Friday'][s.day]].some(v=>v?.toLowerCase().includes(q))}).sort((a,b)=>a.day-b.day||a.time.localeCompare(b.time));let suggestions=q?[...new Set([...subjects,...teachers,...sections,...allRooms.map(r=>r.name)].filter(x=>x.toLowerCase().includes(q)))].slice(0,7):[];return `<main class="workspace finder-page"><div class="page-heading"><div><div class="eyebrow">YOUR WEEK, MADE SIMPLE</div><h1>Find my classes</h1><p>Search a subject, teacher, section, or room to find every class.</p></div><div class="demo-tag"><span>●</span> DEMONSTRATION SCHEDULES</div></div><section class="finder-search"><span>⌕</span><input id="classSearch" value="${esc(state.query)}" placeholder="Try “Grade 10 · Einstein” or “Mathematics”"><kbd>↵</kbd>${suggestions.length?`<div class="suggestions">${suggestions.map(x=>`<button data-suggest="${esc(x)}">${esc(x)}<span>Search →</span></button>`).join('')}</div>`:''}</section><div class="results-head"><div><b>${q?matches.length:0} classes found</b><span>${q?' across your week':' · Start typing to find your schedule'}</span></div><div class="view-tabs">${['Weekly View','Daily View','List View'].map(x=>`<button data-mode="${x}" class="${state.mode===x?'on':''}">${x}</button>`).join('')}</div></div>${q?resultView(matches):`<section class="finder-empty"><div>✳</div><h3>Your next classroom is one search away.</h3><p>Try a subject, teacher, or your section name.</p><div>${['Mathematics','Ms. Santos','Grade 10 · Einstein'].map(x=>`<button data-suggest="${x}">${x} ↗</button>`).join('')}</div></section>`}</main>`}
function resultView(ms){if(state.mode==='Weekly View')return `<div class="week-grid">${['Monday','Tuesday','Wednesday','Thursday','Friday'].map((d,i)=>`<section><h3>${d}</h3>${ms.filter(s=>s.day===i).map(card).join('')||'<p class="day-empty">No classes</p>'}</section>`).join('')}</div>`;if(state.mode==='Daily View')return `<div class="day-select">${['Monday','Tuesday','Wednesday','Thursday','Friday'].map((d,i)=>`<button data-day="${i}" class="${state.day===i?'on':''}">${d}</button>`).join('')}</div><div class="result-list">${ms.filter(s=>s.day===state.day).map(card).join('')||'<p class="day-empty">No classes on this day.</p>'}</div>`;return `<div class="result-list">${ms.map(card).join('')}</div>`}
function card(s){let r=allRooms.find(x=>x.id===s.roomId);return `<article class="result-card"><div class="date-square"><b>${['MON','TUE','WED','THU','FRI'][s.day]}</b><small>${s.time}</small></div><div class="result-subject"><b>${esc(s.subject)}</b><small>${esc(s.teacher)} · ${esc(s.section)}</small></div><div class="result-room"><small>ROOM · FLOOR ${r.floor}</small><b>${esc(r.name)}</b></div><button class="show-map" data-class="${s.id}">SHOW ON MAP <span>↗</span></button></article>`}
function adminPanel(){return `<div class="modal-scrim" id="scrim"><section class="admin-modal"><button class="close" id="closeAdmin">×</button><div class="eyebrow">CAMPUS MANAGEMENT</div><h2>${state.admin?'Admin dashboard':'Administrator sign in'}</h2>${!state.admin?`<p>Demo access: admin@cdm.edu.ph · password: cdm-demo</p><form id="login"><label>Email<input name="email" type="email" value="admin@cdm.edu.ph" required></label><label>Password<input name="password" type="password" placeholder="Enter password" required></label><button class="primary" type="submit">Sign in →</button></form>`:`<div class="admin-summary"><b>${allRooms.length}</b> rooms <b>${schedule.length}</b> schedules</div><div class="admin-actions"><button id="exportData">Export current data (JSON) ↓</button><button id="resetDemo">Restore demonstration schedule ↺</button></div><div class="admin-sections"><button data-admin-section="rooms" class="${state.adminSection==='rooms'?'on':''}">Rooms</button><button data-admin-section="schedules" class="${state.adminSection==='schedules'?'on':''}">Schedules</button></div>${state.adminSection==='rooms'?`<h3>Room directory</h3><div class="room-admin">${allRooms.map(r=>`<div><span><b>${esc(r.name)}</b><small>Floor ${r.floor} · ${r.type}</small></span><button data-edit-room="${r.id}">Edit</button></div>`).join('')}</div><button class="outline full" id="addRoom">＋ Add room</button>`:scheduleAdmin()}<p class="admin-note">Saved changes are kept in this browser. Demo access is not production authentication. Connect Supabase for shared, authenticated school data.</p>`}</section></div>`}
function scheduleAdmin(){let editing=schedule.find(s=>s.id===state.editScheduleId);return `<h3>${editing?'Edit schedule':'Add a schedule'}</h3><form id="scheduleForm" class="schedule-form"><label>Room<select name="roomId">${allRooms.map(r=>`<option value="${r.id}" ${editing?.roomId===r.id?'selected':''}>${esc(r.name)} · Floor ${r.floor}</option>`).join('')}</select></label><label>Day<select name="day">${['Monday','Tuesday','Wednesday','Thursday','Friday'].map((d,i)=>`<option value="${i}" ${editing?.day===i?'selected':''}>${d}</option>`).join('')}</select></label><label>Start<input name="time" type="time" value="${editing?.time||'08:00'}" required></label><label>End<input name="end" type="time" value="${editing?.end||'08:45'}" required></label><label>Subject<input name="subject" value="${esc(editing?.subject||'')}" required></label><label>Teacher<input name="teacher" value="${esc(editing?.teacher||'')}" required></label><label>Section<input name="section" value="${esc(editing?.section||'')}" required></label><button class="primary" type="submit">${editing?'Save schedule':'Add schedule'}</button>${editing?'<button type="button" id="cancelSchedule">Cancel edit</button>':''}</form><h3>Weekly schedule records</h3><div class="room-admin">${schedule.slice(0,100).map(s=>{let r=allRooms.find(x=>x.id===s.roomId);return `<div><span><b>${esc(s.subject)} · ${esc(r?.name||'Room')}</b><small>${['Mon','Tue','Wed','Thu','Fri'][s.day]} ${s.time}–${s.end} · ${esc(s.teacher)} · ${esc(s.section)}</small></span><button data-edit-schedule="${s.id}">Edit</button></div>`}).join('')}</div><p class="admin-note">Showing up to 100 records. Schedules with overlapping times in the same room and day are rejected.</p>`}
function bind(){document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;state.selected=null;render()});$('#adminBtn').onclick=()=>{state.adminOpen=true;render()};$('#closeAdmin')?.addEventListener('click',()=>{state.adminOpen=false;state.admin=false;render()});$('#scrim')?.addEventListener('click',e=>{if(e.target.id==='scrim'){state.adminOpen=false;state.admin=false;render()}});$('#mapSearch')?.addEventListener('input',e=>{state.search=e.target.value;render();$('#mapSearch').focus();$('#mapSearch').setSelectionRange(state.search.length,state.search.length)});$('#classSearch')?.addEventListener('input',e=>{state.query=e.target.value;render();$('#classSearch').focus();$('#classSearch').setSelectionRange(state.query.length,state.query.length)});document.querySelectorAll('[data-floor]').forEach(b=>b.onclick=()=>{state.floor=+b.dataset.floor;state.selected=null;render()});document.querySelectorAll('[data-room]').forEach(g=>{let select=()=>{state.selected=g.dataset.room;state.floor=allRooms.find(r=>r.id===state.selected).floor;render()};g.onclick=select;g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select()}}});document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{state.selected=b.dataset.select;render()});$('#clearSelection')?.addEventListener('click',()=>{state.selected=null;render()});document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{state.day=+b.dataset.day;render()});document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{state.mode=b.dataset.mode;render()});document.querySelectorAll('[data-suggest]').forEach(b=>b.onclick=()=>{state.query=b.dataset.suggest;render()});document.querySelectorAll('[data-class]').forEach(b=>b.onclick=()=>{let s=schedule.find(x=>x.id===b.dataset.class);if(!s)return;let r=allRooms.find(x=>x.id===s.roomId);state.tab='map';state.floor=r.floor;state.selected=r.id;state.day=s.day;state.zoom=1.2;render()});$('#zoomIn')?.addEventListener('click',()=>{state.zoom=Math.min(2.3,state.zoom+.2);render()});$('#zoomOut')?.addEventListener('click',()=>{state.zoom=Math.max(.65,state.zoom-.2);render()});$('#resetZoom')?.addEventListener('click',()=>{state.zoom=1;render()});$('[data-next]')?.addEventListener('click',()=>findNext());$('#login')?.addEventListener('submit',e=>{e.preventDefault();let f=new FormData(e.target);if(f.get('password')==='cdm-demo'){state.admin=true;render()}else alert('Sign in failed. Demo password: cdm-demo')});$('#exportData')?.addEventListener('click',()=>{let blob=new Blob([JSON.stringify({rooms:allRooms,schedules:schedule},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='cdm-campus-data.json';a.click()});$('#resetDemo')?.addEventListener('click',()=>{schedule=makeSchedule();save();render()});$('#addRoom')?.addEventListener('click',()=>{let name=prompt('Room or facility name');if(!name)return;let f=Number(prompt('Floor (1–4)','1'));if(![1,2,3,4].includes(f))return;let room=rows[f].find(r=>r.type==='Classroom');let newRoom={...room,id:`F${f}-${Date.now()}`,name,x:room.x,y:room.y,w:room.w,h:room.h,type:'Classroom',description:'New room added in the admin dashboard.'};rows[f].push(newRoom);allRooms.push(newRoom);save();render()});document.querySelectorAll('[data-edit-room]').forEach(b=>b.onclick=()=>{let r=allRooms.find(x=>x.id===b.dataset.editRoom),name=prompt('Edit room name',r.name);if(name){r.name=name;save();render()}});window.onkeydown=e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();(state.tab==='map'?$('#mapSearch'):$('#classSearch'))?.focus()}if(e.key==='Escape'&&state.adminOpen){state.adminOpen=false;state.admin=false;render()}};bindAdminCrud()}
function bindAdminCrud(){document.querySelectorAll('[data-admin-section]').forEach(b=>b.onclick=()=>{state.adminSection=b.dataset.adminSection;state.editScheduleId=null;render()});document.querySelectorAll('[data-edit-schedule]').forEach(b=>b.onclick=()=>{state.editScheduleId=b.dataset.editSchedule;render()});$('#cancelSchedule')?.addEventListener('click',()=>{state.editScheduleId=null;render()});$('#scheduleForm')?.addEventListener('submit',e=>{e.preventDefault();let form=new FormData(e.target),candidate={id:state.editScheduleId||`admin-${Date.now()}`,roomId:form.get('roomId'),day:Number(form.get('day')),time:form.get('time'),end:form.get('end'),subject:form.get('subject').trim(),teacher:form.get('teacher').trim(),section:form.get('section').trim(),demo:false};let mins=t=>{let[h,m]=t.split(':').map(Number);return h*60+m};if(mins(candidate.end)<=mins(candidate.time)){alert('The end time must be after the start time.');return}let conflict=schedule.some(s=>s.id!==candidate.id&&s.roomId===candidate.roomId&&s.day===candidate.day&&mins(candidate.time)<mins(s.end)&&mins(s.time)<mins(candidate.end));if(conflict){alert('This room already has a class during that time.');return}if(state.editScheduleId){let i=schedule.findIndex(s=>s.id===state.editScheduleId);schedule[i]=candidate}else schedule.push(candidate);state.editScheduleId=null;save();render()})}
function findNext(){let now=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Manila'})),d=now.getDay()-1,m=now.getHours()*60+now.getMinutes(),next=schedule.filter(s=>s.day>=Math.max(0,d)).sort((a,b)=>a.day-b.day||a.time.localeCompare(b.time)).find(s=>{if(s.day!==d)return true;let[h,x]=s.time.split(':').map(Number);return h*60+x>m});if(!next){alert('No more classes are scheduled for the school week.');return}let r=allRooms.find(x=>x.id===next.roomId);state.tab='map';state.floor=r.floor;state.selected=r.id;state.day=next.day;state.zoom=1.2;render()}
setInterval(()=>{if(state.tab==='map')render()},60000);render();
